  // ── Screen: atlas ─────────────────────────────────────────────────────────────────────
  'help.ctx.atlas.title': 'Atlas',
  'help.ctx.atlas.summary':
    'Το Atlas είναι το ταξιδιωτικό σας αποτύπωμα σε έναν παγκόσμιο χάρτη: κάθε χώρα όπου σας πήγε ένα ταξίδι είναι χρωματισμένη, και όσες επισκεφθήκατε πριν από το TREK τις προσθέτετε με το χέρι. Κάντε ζουμ για περιφέρειες, κρατήστε μια λίστα επιθυμιών με μέρη που θέλετε ακόμη να δείτε και διαβάστε τους αριθμούς σας στο γυάλινο πάνελ κάτω.',
  'help.ctx.atlas.bullet.1':
    'Ο χάρτης: οι χώρες που επισκεφθήκατε έχουν ένα χρώμα που μένει δικό τους, οι προγραμματισμένες έχουν διακεκομμένο περίγραμμα, οι χώρες της λίστας επιθυμιών διαγώνια γραμμοσκίαση, όλα τα άλλα είναι γκρι. Περάστε τον δείκτη πάνω από μια χώρα για τα ταξίδια, τα μέρη και την πρώτη και τελευταία επίσκεψη.',
  'help.ctx.atlas.bullet.2':
    'Αναζήτηση πάνω: πληκτρολογήστε χώρα ή μέρος. Η επιλογή χώρας μεταφέρει τον χάρτη εκεί και ανοίγει το παράθυρό της· η επιλογή μέρους προσγειώνεται στην περιφέρειά του για να τη σημειώσετε.',
  'help.ctx.atlas.bullet.3':
    'Εμφάνιση προγραμματισμένων χωρών, πάνω δεξιά: αποκαλύπτει τις χώρες των επερχόμενων ταξιδιών σας. Ο διακόπτης εμφανίζεται μόνο όσο έχετε τέτοια.',
  'help.ctx.atlas.bullet.4':
    'Πάνελ κάτω: η καρτέλα Στατιστικά με χώρες, ταξίδια, μέρη, πόλεις, ημέρες, ηπείρους και το σερί σας· η καρτέλα Λίστα Επιθυμιών με ό,τι έχετε ακόμη μπροστά σας.',
  'help.ctx.atlas.bullet.5':
    'Περιφέρειες: από το επίπεδο ζουμ 5 ο χάρτης περνά σε πολιτείες και επαρχίες, καθεμία με κλικ για σήμανση ή αφαίρεση.',
  'help.ctx.atlas.bullet.6':
    'Dawarich: με συνδεδεμένο το πρόσθετο, ένα πάνελ αριστερά από τα στατιστικά τσεκάρει επιθυμίες και προσθέτει χώρες από τις καταγραφές σας, ποτέ χωρίς την επιβεβαίωσή σας.',
  // mark-country
  'help.guide.mark-country.title': 'Σήμανση χώρας ως επισκεφθείσας',
  'help.guide.mark-country.goal':
    'Προσθέστε μια χώρα όπου πήγατε πριν από το TREK, ώστε ο χάρτης και ο μετρητής σας να την περιλαμβάνουν.',
  'help.guide.mark-country.step.1': 'Πληκτρολογήστε τη χώρα στο πλαίσιο αναζήτησης στην κορυφή του χάρτη.',
  'help.guide.mark-country.step.2':
    'Επιλέξτε την από τη λίστα. Ο χάρτης πετά εκεί και ανοίγει ένα παράθυρο για τη χώρα.',
  'help.guide.mark-country.step.3': 'Επιλέξτε Σήμανση ως επισκεφθείσα.',
  'help.guide.mark-country.result':
    'Η χώρα παίρνει το χρώμα της στον χάρτη και οι Χώρες μετρούν μία παραπάνω. Το χρώμα είναι μόνιμο: η σήμανση περισσότερων χωρών δεν ανακατεύει ποτέ τις υπόλοιπες.',
  'help.guide.mark-country.tip.1':
    'Το κλικ σε μια γκρι χώρα στον χάρτη ανοίγει το ίδιο παράθυρο· η αναζήτηση είναι ο σίγουρος δρόμος για μικρές χώρες.',
  'help.guide.mark-country.tip.2':
    'Μια χώρα που σημειώνετε με το χέρι μετρά πάντα ως επισκεφθείσα, όποιες κι αν είναι οι ημερομηνίες ενός ταξιδιού εκεί.',
  // unmark-country
  'help.guide.unmark-country.title': 'Αφαίρεση χώρας που σημειώσατε',
  'help.guide.unmark-country.goal': 'Βγάλτε ξανά από τον χάρτη μια χώρα που σημειώσατε με το χέρι.',
  'help.guide.unmark-country.step.1':
    'Αναζητήστε τη χώρα και επιλέξτε την, ή κάντε κλικ πάνω της στον χάρτη. Για χώρα που σημειώσατε εσείς, το παράθυρο ρωτά αν θα αφαιρεθεί.',
