  'help.guide.unmark-country.result': 'Η χώρα γίνεται ξανά γκρι και φεύγει από τον μετρητή σας.',
  'help.guide.unmark-country.tip.1':
    'Μόνο χώρες σημειωμένες με το χέρι αφαιρούνται έτσι. Μια χώρα με ταξίδια ή μέρη μένει όσο τα έχει· η Αφαίρεση υπάρχει και στην κάρτα λεπτομερειών της στο πάνελ όταν σημειώθηκε με το χέρι.',
